        outline-offset: 3px;
      }

      .submit-row {
        margin-top: 1.5rem;
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.35rem;
        background: linear-gradient(180deg, var(--accent-strong), var(--accent));
        color: #0b1020;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(124, 156, 255, 0.25);
        transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
      }

      button:hover {
        filter: brightness(1.03);
        transform: translateY(-1px);
      }

      button:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 4px;
      }

      .status {
        min-height: 1.5rem;
        color: var(--muted);
      }

      @media (max-width: 540px) {
        main {
          padding-inline: 0.875rem;
          padding-top: 4.5rem;
        }

        .page-shell {
          padding: 1.35rem;
