         background: linear-gradient(180deg, rgba(124, 156, 255, 0.1), rgba(255, 255, 255, 0.02));
       }

       .radio-option input:checked + .radio-card {
         border-color: rgba(124, 156, 255, 0.95);
         background: linear-gradient(180deg, rgba(124, 156, 255, 0.18), rgba(255, 255, 255, 0.03));
         box-shadow: inset 0 0 0 1px rgba(124, 156, 255, 0.18);
       }

       .radio-option input:checked + .radio-card .radio-dot {
         border-color: var(--accent-strong);
       }

       .radio-option input:checked + .radio-card .radio-dot::after {
         background: var(--accent-strong);
       }

       .radio-option input:focus-visible + .radio-card {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .submit-row {
         margin-top: 1.5rem;
         display: flex;
         flex-wrap: wrap;
         gap: 0.75rem;
         align-items: center;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.35rem;
         background: linear-gradient(180deg, var(--accent-strong), var(--accent));
         color: #0b1020;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 12px 24px rgba(124, 156, 255, 0.25);
         transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
       }

       button:hover {
         filter: brightness(1.03);
         transform: translateY(-1px);
       }

       button:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 4px;
       }

       .status {
         min-height: 1.5rem;
         color: var(--muted);
       }

       @media (max-width: 540px) {
         main {
           padding-inline: 0.875rem;
           padding-top: 4.5rem;
         }

         .page-shell {
           padding: 1.35rem;
           border-radius: 1.25rem;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="page-shell" aria-labelledby="page-title">
         <h1 id="page-title">Notification preferences</h1>
         <p class="intro">Choose how you'd like to receive updates about your account and activity.</p>

         <form id="notification-form" novalidate>
           <div class="form-field">
             <fieldset aria-describedby="notification-help">
               <legend>
                 How do you prefer to receive notifications?
                 <span class="required-indicator" aria-hidden="true">*</span>
               </legend>
               <p class="help-text" id="notification-help">Select one option to continue.</p>

               <div class="radio-group">
                 <label class="radio-option">
                   <input type="radio" name="notification-method" value="Email" required>
                   <span class="radio-card">
                     <span class="radio-dot" aria-hidden="true"></span>
                     <span class="radio-label">Email</span>
                   </span>
                 </label>

                 <label class="radio-option">
                   <input type="radio" name="notification-method" value="SMS" required>
                   <span class="radio-card">
                     <span class="radio-dot" aria-hidden="true"></span>
                     <span class="radio-label">SMS</span>
                   </span>
                 </label>

                 <label class="radio-option">
                   <input type="radio" name="notification-method" value="Push Notifications" required>
                   <span class="radio-card">
                     <span class="radio-dot" aria-hidden="true"></span>
                     <span class="radio-label">Push Notifications</span>
                   </span>
                 </label>
               </div>
             </fieldset>
           </div>

           <div class="submit-row">
             <button type="submit">Save preference</button>
             <p class="status" id="form-status" role="status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById('notification-form');
       const status = document.getElementById('form-status');

       form.addEventListener('submit', (event) => {
         event.preventDefault();

         if (!form.checkValidity()) {
           form.reportValidity();
           status.textContent = '';
           return;
         }

         const selected = form.elements['notification-method'].value;
         status.textContent = `Preference saved: ${selected}.`;
       });
     </script>
   </body>
 </html>

